insert into public.tax_rules (key, value, year, jurisdiction, source_url, verified_at, reviewed_by) values
  ('state_return_nonresident', '{"must_file_if": "nonresident with Colorado source income AND (required to file a federal return OR Colorado income tax liability)", "summary": {"es": "Según el Colorado Department of Revenue, los no residentes con ingresos de fuente de Colorado declaran si tienen que presentar declaración federal o si tienen impuesto de Colorado por pagar.", "en": "According to the Colorado Department of Revenue, nonresidents with Colorado-source income must file if they are required to file a federal return or have a Colorado tax liability."}}'::jsonb, 2026, 'CO', 'https://tax.colorado.gov/individual-income-tax-filing-requirements', '2026-10-30', 'pendiente Enrolled Agent'),
  ('state_return_nonresident', '{"must_file_if": "nonresident with income from Utah sources who must file a federal return", "form": "TC-40", "summary": {"es": "Según la Utah State Tax Commission, los no residentes con ingresos de fuente de Utah que deben presentar declaración federal presentan el Form TC-40.", "en": "According to the Utah State Tax Commission, nonresidents with income from Utah sources who must file a federal return file Form TC-40."}}'::jsonb, 2026, 'UT', 'https://incometax.utah.gov/instructions/who-must-file', '2026-10-30', 'pendiente Enrolled Agent'),
  ('state_return_nonresident', '{"must_file_if": "generally, nonresident who receives income from a source in California (FTB filing thresholds apply)", "summary": {"es": "Según el Franchise Tax Board, en general un no residente debe declarar si recibe ingresos de fuente de California. Hay montos mínimos: revísalos en la fuente.", "en": "According to the Franchise Tax Board, a nonresident generally must file if they receive income from a source in California. Minimum amounts apply: check the source."}}'::jsonb, 2026, 'CA', 'https://www.ftb.ca.gov/file/personal/do-you-need-to-file.html', '2026-10-30', 'pendiente Enrolled Agent'),
  ('state_return_nonresident', '{"must_file_if": "nonresident with total gross income from Idaho sources over 2500 USD", "gross_income_threshold_usd": 2500, "form": "Form 43", "summary": {"es": "Según la Idaho State Tax Commission, los no residentes declaran (Form 43) si sus ingresos brutos de fuente de Idaho pasan de $2,500.", "en": "According to the Idaho State Tax Commission, nonresidents file (Form 43) if their gross income from Idaho sources is more than $2,500."}}'::jsonb, 2026, 'ID', 'https://tax.idaho.gov/taxes/income-tax/individual-income/online-guide/', '2026-10-30', 'pendiente Enrolled Agent'),
  ('state_return_nonresident', '{"must_file_if": "nonresident with Vermont net income over 100 USD or gross income over 1000 USD", "net_income_threshold_usd": 100, "gross_income_threshold_usd": 1000, "form": "IN-111 + Schedule IN-113", "summary": {"es": "Según el Vermont Department of Taxes, los no residentes declaran (Form IN-111 con Schedule IN-113) si su ingreso neto de Vermont pasa de $100 o su ingreso bruto pasa de $1,000.", "en": "According to the Vermont Department of Taxes, nonresidents file (Form IN-111 with Schedule IN-113) if their Vermont net income is more than $100 or gross income more than $1,000."}}'::jsonb, 2026, 'VT', 'https://tax.vermont.gov/individuals/who-should-file/nonresident', '2026-10-30', 'pendiente Enrolled Agent'),
  ('state_return_due_date', '{"calendar_year": "04-15", "extension": "10-15"}'::jsonb, 2026, 'CO', 'https://tax.colorado.gov/index.php/income-tax-due-dates-filing-extension', '2026-10-30', 'pendiente Enrolled Agent'),
  ('state_return_due_date', '{"calendar_year": "04-15", "extension": "10-15", "note": "Extension is automatic to file, not to pay"}'::jsonb, 2026, 'CA', 'https://www.ftb.ca.gov/file/when-to-file/due-dates-personal.html', '2026-10-30', 'pendiente Enrolled Agent'),
  ('state_return_due_date', '{"calendar_year": "04-15", "note": "Extensions do not extend time to pay"}'::jsonb, 2026, 'ID', 'https://tax.idaho.gov/taxes/income-tax/individual-income/filing-and-paying/', '2026-10-30', 'pendiente Enrolled Agent'),
  ('state_return_due_date', '{"calendar_year": "04-15", "extension": "10-15"}'::jsonb, 2026, 'VT', 'https://tax.vermont.gov/individuals/personal-income-tax', '2026-10-30', 'pendiente Enrolled Agent')
