-- Declaración estatal de no residentes y fechas límite: CO, UT, CA, ID, VT (verificado 2026-10-30).
-- Generado por scripts/state-returns.py. WY y NH quedan pendientes (sin fuente oficial clara).
on conflict (key, jurisdiction, year) do update set value = excluded.value, source_url = excluded.source_url, verified_at = excluded.verified_at;

-- Montana: resumen bilingüe para la app (mismo contenido de la fuente).
update public.tax_rules set value = value || jsonb_build_object('summary', '{"es": "Según el Montana Department of Revenue, los no residentes con ingresos de fuente de Montana y obligación de declarar a nivel federal también declaran en Montana. Hay una excepción si solo ganaste sueldo por trabajar ahí 30 días o menos y trabajaste en más de un estado.", "en": "According to the Montana Department of Revenue, nonresidents with Montana-source income and a federal filing requirement also file in Montana. There is an exception if you only earned wages for 30 days or less there and worked in more than one state."}'::jsonb)
where key = 'state_return_nonresident' and jurisdiction = 'MT';
